package app

import (
	"context"
	"encoding/base64"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/project"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
)

type SprintSummary struct {
	Project             string
	Slug                string
	Status              string
	FlowStatePath       string
	ExecutePath         string
	RunStatePath        string
	ReviewPath          string
	SmokePath           string
	Stages              []StageSummary
	Execute             ExecuteSummary
	Review              ReviewSummary
	Smoke               SmokeSummary
	Merge               MergeSummary
	QA                  QAResult
	Repair              RepairStatusResult
	Performance         PerformanceStatusResult
	PerformanceEvidence PerformanceEvidenceResult
	Findings            []DisplayFinding
	Artifacts           []DisplayArtifact
	RefreshMayWrite     bool
	RefreshActionNote   string
	Assessment          string
	NextAction          string
}

// PerformanceUseCases is the adapter-neutral, sample-free performance query
// boundary. Mutating work still uses the shared durable operation bridge.
type PerformanceUseCases interface {
	PreparePerformance(context.Context, PerformanceRequest) (PerformancePrepareResult, error)
	PerformanceStatus(context.Context, PerformanceRequest) (PerformanceStatusResult, error)
	PerformanceResult(context.Context, PerformanceRequest) (PerformanceStatusResult, error)
	PerformanceEvidence(context.Context, PerformanceRequest) (PerformanceEvidenceResult, error)
}

type PerformanceRequest struct {
	Project string `json:"project"`
	Sprint  string `json:"sprint"`
	Cursor  string `json:"cursor,omitempty"`
	Filter  string `json:"filter,omitempty"`
	Limit   int    `json:"limit,omitempty"`
}

type PerformancePrepareResult struct {
	SchemaVersion    int                        `json:"schema_version"`
	Project          string                     `json:"project"`
	Sprint           string                     `json:"sprint"`
	PolicyMode       string                     `json:"policy_mode"`
	PolicyDigest     string                     `json:"policy_digest,omitempty"`
	Enabled          bool                       `json:"enabled"`
	Ready            bool                       `json:"ready"`
	DryRun           bool                       `json:"dry_run"`
	MutationPossible bool                       `json:"mutation_possible"`
	Targets          []PerformanceTargetSummary `json:"targets,omitempty"`
	Missing          []string                   `json:"missing_prerequisites,omitempty"`
	Limits           sprint.PerformanceLimits   `json:"limits"`
	LimitSources     map[string]string          `json:"limit_sources,omitempty"`
	NextAction       string                     `json:"next_action"`
}

type PerformanceStatusResult struct {
	SchemaVersion        int                         `json:"schema_version"`
	Project              string                      `json:"project"`
	Sprint               string                      `json:"sprint"`
	PolicyMode           string                      `json:"policy_mode"`
	Enabled              bool                        `json:"enabled"`
	Ready                bool                        `json:"ready"`
	Phase                string                      `json:"phase"`
	Fresh                bool                        `json:"fresh"`
	FreshnessReasons     []string                    `json:"freshness_reasons,omitempty"`
	PerformanceAttemptID string                      `json:"performance_attempt_id,omitempty"`
	OperationRunID       string                      `json:"operation_run_id,omitempty"`
	OperationalAttemptID string                      `json:"operational_attempt_id,omitempty"`
	OperationalLifecycle string                      `json:"operational_lifecycle,omitempty"`
	CancellationState    string                      `json:"cancellation_state,omitempty"`
	FencingGeneration    uint64                      `json:"fencing_generation,omitempty"`
	Outcome              string                      `json:"outcome,omitempty"`
	Targets              []PerformanceTargetSummary  `json:"targets,omitempty"`
	Consumed             sprint.PerformanceCounters  `json:"consumed"`
	Limits               sprint.PerformanceLimits    `json:"limits"`
	LimitSources         map[string]string           `json:"limit_sources,omitempty"`
	State                *PerformanceArtifactSummary `json:"state,omitempty"`
	Result               *PerformanceArtifactSummary `json:"result,omitempty"`
	Blocker              string                      `json:"blocker,omitempty"`
	NextAction           string                      `json:"next_action"`
}

type PerformanceTargetSummary struct {
	ID                    string                           `json:"id"`
	Scenario              string                           `json:"scenario"`
	Metric                string                           `json:"metric"`
	Comparator            string                           `json:"comparator"`
	Value                 string                           `json:"value"`
	Unit                  string                           `json:"unit"`
	Gate                  string                           `json:"gate"`
	Samples               int                              `json:"samples"`
	Basis                 string                           `json:"basis"`
	BaselineQualification *sprint.PerformanceQualification `json:"baseline_qualification,omitempty"`
	FinalQualification    *sprint.PerformanceQualification `json:"final_qualification,omitempty"`
	Comparison            string                           `json:"comparison,omitempty"`
	Outcome               string                           `json:"outcome,omitempty"`
}

type PerformanceArtifactSummary struct {
	Path   string `json:"path"`
	Digest string `json:"digest"`
}

type PerformanceEvidenceResult struct {
	SchemaVersion int                                `json:"schema_version"`
	Records       []sprint.PerformanceEvidenceRecord `json:"records"`
	NextCursor    string                             `json:"next_cursor,omitempty"`
	ReturnedCount int                                `json:"returned_count"`
}

func (u dashboardUseCases) PreparePerformance(ctx context.Context, req PerformanceRequest) (PerformancePrepareResult, error) {
	if err := ctx.Err(); err != nil {
		return PerformancePrepareResult{}, err
	}
	prepared, err := u.sprintService().PreparePerformance(req.Project, req.Sprint, true)
	if err != nil {
		return PerformancePrepareResult{}, mapPerformanceUseCaseError("performance.prepare", err)
	}
	return performancePrepareProjection(prepared), nil
}

func (u dashboardUseCases) PerformanceStatus(ctx context.Context, req PerformanceRequest) (PerformanceStatusResult, error) {
	if err := ctx.Err(); err != nil {
		return PerformanceStatusResult{}, err
	}
	result, err := performanceStatusProjection(u.sprintService(), req.Project, req.Sprint)
	if err == nil && u.runs != nil && result.OperationRunID != "" {
		if snapshot, runErr := u.runs.Run(ctx, RunID(result.OperationRunID)); runErr == nil {
			result.OperationalLifecycle, result.CancellationState = string(snapshot.Lifecycle), string(snapshot.Cancellation.State)
		}
	}
	return result, mapPerformanceUseCaseError("performance.status", err)
}

func (u dashboardUseCases) PerformanceResult(ctx context.Context, req PerformanceRequest) (PerformanceStatusResult, error) {
	status, err := u.PerformanceStatus(ctx, req)
	if err != nil {
		return status, err
	}
	if status.Result == nil {
		return status, fmt.Errorf("performance result is unavailable")
	}
	return status, nil
}

func (u dashboardUseCases) PerformanceEvidence(ctx context.Context, req PerformanceRequest) (PerformanceEvidenceResult, error) {
	if err := ctx.Err(); err != nil {
		return PerformanceEvidenceResult{}, err
	}
	page, err := u.sprintService().PerformanceEvidence(req.Project, req.Sprint, req.Cursor, req.Filter, req.Limit)
	if err != nil {
		return PerformanceEvidenceResult{}, mapPerformanceUseCaseError("performance.evidence", err)
	}
	return PerformanceEvidenceResult{SchemaVersion: 1, Records: page.Records, NextCursor: page.NextCursor, ReturnedCount: len(page.Records)}, nil
}

func performancePrepareProjection(prepared sprint.PerformancePrepareResult) PerformancePrepareResult {
	result := PerformancePrepareResult{SchemaVersion: 1, Project: prepared.Project, Sprint: prepared.Sprint, PolicyMode: prepared.PolicyMode, PolicyDigest: prepared.PolicyDigest, Enabled: prepared.Enabled, Ready: prepared.Ready, DryRun: prepared.DryRun, MutationPossible: prepared.MutationPossible, Missing: qaDisplayStrings(prepared.Missing), Limits: prepared.Limits, LimitSources: prepared.LimitSources, NextAction: displaySafe(prepared.NextAction)}
	for _, target := range prepared.Packet.Targets {
		result.Targets = append(result.Targets, performanceTargetProjection(target))
	}
	return result
}

func performanceStatusProjection(service sprint.Service, projectRef, sprintRef string) (PerformanceStatusResult, error) {
	prepared, err := service.PreparePerformance(projectRef, sprintRef, true)
	if err != nil {
		return PerformanceStatusResult{}, err
	}
	result := PerformanceStatusResult{SchemaVersion: 1, Project: prepared.Project, Sprint: prepared.Sprint, PolicyMode: prepared.PolicyMode, Enabled: prepared.Enabled, Ready: prepared.Ready, Phase: string(sprint.PerformancePhaseReady), Fresh: true, Limits: prepared.Limits, LimitSources: prepared.LimitSources, NextAction: displaySafe(prepared.NextAction)}
	for _, target := range prepared.Packet.Targets {
		result.Targets = append(result.Targets, performanceTargetProjection(target))
	}
	if !prepared.Enabled {
		return result, nil
	}
	state, err := service.PerformanceStatus(projectRef, sprintRef)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			result.Fresh = true
			result.NextAction = displaySafe(prepared.NextAction)
			return result, nil
		}
		return result, err
	}
	result.Phase, result.Fresh, result.FreshnessReasons, result.PerformanceAttemptID, result.OperationRunID, result.OperationalAttemptID, result.FencingGeneration, result.Outcome = string(state.Phase), state.Fresh, qaDisplayStrings(state.FreshnessReasons), state.AttemptID, state.Correlation.RunID, state.Correlation.OperationalAttemptID, state.Correlation.FencingGeneration, string(state.Outcome)
	result.Consumed, result.Limits, result.Blocker, result.NextAction = state.Counters, state.Limits, displaySafe(state.Blocker), displaySafe(state.NextAction)
	if state.Result != nil {
		result.Result = performanceArtifactProjection(*state.Result)
		terminal, resultErr := service.PerformanceCurrentResult(projectRef, sprintRef)
		if resultErr != nil {
			return result, resultErr
		}
		result.Targets = result.Targets[:0]
		for _, target := range terminal.TargetResults {
			projected := performanceTargetProjection(target.Target)
			baseline, final := target.BaselineQualification, target.FinalQualification
			projected.BaselineQualification, projected.FinalQualification = &baseline, &final
			projected.Comparison, projected.Outcome = target.Comparison.ComparedValue, string(target.Comparison.Outcome)
			result.Targets = append(result.Targets, projected)
		}
	}
	return result, nil
}

func performanceTargetProjection(target sprint.PerformanceTarget) PerformanceTargetSummary {
	return PerformanceTargetSummary{ID: target.ID, Scenario: displaySafe(target.Scenario), Metric: displaySafe(target.Metric), Comparator: string(target.Comparator), Value: target.Value, Unit: string(target.Unit), Gate: string(target.Gate), Samples: target.Samples, Basis: string(target.Basis)}
}

func performanceArtifactProjection(ref sprint.PerformanceArtifactRef) *PerformanceArtifactSummary {
	if ref.Path == "" || ref.Digest == "" {
		return nil
	}
	return &PerformanceArtifactSummary{Path: ref.Path, Digest: ref.Digest}
}

type ReviewSummary struct {
	Available                bool
	Status, Verdict          string
	Error                    string
	Stale                    bool
	Completed, Total         int
	Pending, Running, Failed int
	Artifact, Digest         string
	FreshnessReasons         []string
	Reviewers                []ReviewItemSummary
