func (u *webUseCases) Sprint(ctx context.Context, project, slug string) (WebSprintResult, error) {
	items, err := u.dashboard.SprintSummaries(ctx)
	if err != nil {
		return WebSprintResult{}, err
	}
	for _, item := range items {
		if item.Project == project && item.Slug == slug {
			result := u.webSprint(item)
			result.AttentionFindings = append([]DisplayFinding(nil), result.Findings...)
			if len(result.AttentionFindings) > 3 {
				result.AttentionFindings = result.AttentionFindings[:3]
			}
			result.Overview = u.sprintOverview(project, slug)
			result.RunStages = sprintRunStages(item)
			u.annotateStageModels(&result)
			result.TotalStages = len(result.RunStages)
			for _, stage := range result.RunStages {
				if stage.Status == "complete" || stage.Status == "completed" || stage.Status == "skipped" {
					result.CompletedStages++
					continue
				}
				if result.CurrentStage == "" {
					result.CurrentStage = stage.Name
				}
			}
			u.enrichSprintDashboard(&result)
			return result, nil
		}
	}
	return WebSprintResult{}, ErrWebNotFound
}

func (u *webUseCases) PromptBundle(ctx context.Context, project, slug, stageName string) (WebPromptBundleResult, error) {
	if err := ctx.Err(); err != nil {
		return WebPromptBundleResult{}, err
	}
	stage := sprint.PlanningStage(stageName)
	result := WebPromptBundleResult{
		Stage:         stage,
		Scope:         "Deterministic stage preview",
		InputContract: sprint.InputContract(stage),
	}
	service := u.dashboard.sprintService()
	var (
		preview sprint.PromptPreview
		err     error
	)
	switch stage {
	case sprint.StageRequirements:
		preview, err = service.PromptRequirements(project, slug)
	case sprint.StageCodeContext:
		preview, err = service.PromptCodeContext(project, slug)
	case sprint.StageSprintIndex:
		preview, err = service.PromptSprintIndex(project, slug)
	case sprint.StageTechnicalHandbook:
		preview, err = service.PromptTechnicalHandbook(project, slug)
	case sprint.StageAreaReasoning:
		result.Scope = "First selected area prompt"
		preview, err = service.PromptAreaReasoning(project, slug)
	case sprint.StageReasoning:
		preview, err = service.PromptReasoning(project, slug)
	case sprint.StagePlan:
		preview, err = service.PromptPlan(project, slug)
	case sprint.StageExecute:
		result.Scope = "One session for the ordered task queue"
		preview, err = service.PromptExecute(project, slug, sprint.ExecuteRequest{})
	case sprint.StageReview:
		result.Scope = "Conformance Review manifest preview; worker suffixes vary"
		preview, err = service.PromptReview(project, slug, sprint.ReviewRequest{})
	case sprint.StageSmoke:
		result.Scope = "Prepared after smoke harness discovery"
		result.UnavailableReason = "The smoke prompt is assembled only after the governed harness and acceptance coverage are discovered."
		return result, nil
	case sprint.StageMerge:
		result.Scope = "Prepared from frozen Git identities after merge admission"
		result.UnavailableReason = "The merge description prompt is assembled only after UltraPlan validates both recorded worktrees and current verification evidence."
		return result, nil
	default:
		return WebPromptBundleResult{}, ErrWebNotFound
	}
	if err := ctx.Err(); err != nil {
		return WebPromptBundleResult{}, err
	}
	if err != nil {
		result.UnavailableReason = displaySafe(err.Error())
		return result, nil
	}
	explanation := preview.Explanation
	if explanation == nil {
		value := sprint.ExplainPrompt(preview.Prompt)
		explanation = &value
	}
	contract := result.InputContract
	explanation.InputContract = &contract
	result.Available = true
	result.Explanation = explanation
	result.BlockContents = make([]string, 0, len(explanation.Blocks))
	offset := 0
	for _, block := range explanation.Blocks {
		end := offset + block.Bytes
		if end > len(preview.Prompt) {
			result.BlockContents = nil
			break
		}
		result.BlockContents = append(result.BlockContents, preview.Prompt[offset:end])
		offset = end
	}
	return result, nil
}

func (u *webUseCases) sprintOverview(project, slug string) string {
	path := filepath.Join(u.root, "projects", project, "sprints", slug, "requirements.md")
	data, err := os.ReadFile(path)
	if err != nil {
		return ""
	}
	lines := strings.Split(string(data), "\n")
	inGoal := false
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "## ") {
			if inGoal {
				break
			}
			inGoal = strings.EqualFold(strings.TrimSpace(strings.TrimPrefix(trimmed, "## ")), "Sprint Goal")
			continue
		}
		if inGoal && trimmed != "" {
			return strings.Trim(strings.TrimSpace(trimmed), "`*")
		}
	}
	return ""
}

// dashboardMarkdown is a deliberately small reader for governed Markdown. It
// extracts useful previews while leaving the source documents authoritative.
type dashboardMarkdown struct {
	sections map[string][]string
	order    []string
}

func readDashboardMarkdown(path string) dashboardMarkdown {
	result := dashboardMarkdown{sections: map[string][]string{}}
	file, err := os.Open(path)
	if err != nil {
		return result
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, 64<<10))
	if err != nil {
		return result
	}
	section := ""
	for _, raw := range strings.Split(string(data), "\n") {
		line := strings.TrimSpace(raw)
		if strings.HasPrefix(line, "## ") {
			section = strings.ToLower(strings.TrimSpace(strings.TrimPrefix(line, "## ")))
			result.order = append(result.order, section)
			continue
		}
		if section != "" && line != "" && !strings.HasPrefix(line, "<!--") {
			result.sections[section] = append(result.sections[section], line)
		}
	}
	return result
}

func (m dashboardMarkdown) first(names ...string) string {
	for _, name := range names {
		for _, heading := range m.order {
			lines := m.sections[heading]
			if strings.EqualFold(heading, name) || strings.Contains(heading, strings.ToLower(name)) {
				for _, line := range lines {
					clean := cleanDashboardLine(line)
					if clean != "" {
						return clean
					}
				}
			}
		}
	}
	return ""
}

func (m dashboardMarkdown) items(names ...string) []string {
	var out []string
	for _, name := range names {
		for _, heading := range m.order {
			lines := m.sections[heading]
			if !strings.EqualFold(heading, name) && !strings.Contains(heading, strings.ToLower(name)) {
				continue
			}
			for _, line := range lines {
				if strings.HasPrefix(line, "- ") || strings.HasPrefix(line, "* ") || strings.HasPrefix(line, "1. ") {
					if value := cleanDashboardLine(line); value != "" {
						out = append(out, value)
					}
				}
			}
		}
	}
	return out
}

func cleanDashboardLine(line string) string {
	line = strings.TrimSpace(line)
	line = strings.TrimPrefix(strings.TrimPrefix(strings.TrimPrefix(line, "- "), "* "), "1. ")
	line = strings.Trim(line, "`*# ")
	if strings.HasPrefix(line, "[") && strings.Contains(line, "]:") {
		line = strings.TrimSpace(strings.SplitN(line, "]:", 2)[1])
	}
	return line
}

func countDashboardItems(m dashboardMarkdown, names ...string) int {
	return len(m.items(names...))
}

func (u *webUseCases) enrichProjectDashboard(result *WebProjectResult) {
	base := filepath.Join(u.root, "projects", result.Name)
	index := readDashboardMarkdown(filepath.Join(base, "project-index.md"))
	result.Brief = WebProjectBrief{
		Goal:       index.first("project summary", "primary goal", "goal"),
		Phase:      index.first("current phase", "product phase", "phase"),
		Repository: index.first("target repository", "repository"),
		Validation: index.first("validation", "last validation"),
		NonGoals:   index.items("non-goals", "non goals"),
	}
	if result.Brief.Goal == "" {
		result.Brief.Goal = "Project goal has not been recorded in project-index.md."
	}
	for _, phase := range result.Roadmap {
		for _, item := range phase.Sprints {
			switch item.Status {
			case "delivered":
				result.Delivered++
			case "active":
				result.Active++
			default:
				result.Planned++
			}
		}
	}
	for _, sprint := range result.Sprints {
		if len(sprint.Findings) > 0 || sprint.Review.Stale || sprint.Smoke.Stale || sprint.Review.Failed > 0 || sprint.Execute.Failed > 0 {
			result.NeedsAttention++
		}
	}
	wanted := []struct{ file, kind string }{{"PRD.md", "Product"}, {"TRD.md", "Technical"}, {"ARCHITECTURE.md", "Architecture"}}
	for _, doc := range wanted {
		path := filepath.Join(base, doc.file)
		ref := ""
		for _, artifact := range result.Artifacts {
			if strings.EqualFold(filepath.Base(artifact.DisplayPath), doc.file) {
				path = filepath.Join(u.root, filepath.FromSlash(artifact.DisplayPath))
				ref = artifact.Ref
				break
			}
		}
		parsed := readDashboardMarkdown(path)
		if len(parsed.order) == 0 {
			continue
		}
		preview := WebDocumentPreview{Kind: doc.kind, Name: doc.file, Sections: len(parsed.order), Summary: parsed.first("goal", "summary", "overview", "purpose")}
		if preview.Summary == "" {
			preview.Summary = parsed.first(parsed.order[0])
		}
		if info, err := os.Stat(path); err == nil {
			preview.Modified = info.ModTime().Format("2 Jan 2006")
		}
		preview.Ref = ref
		result.Documents = append(result.Documents, preview)
	}
}

func (u *webUseCases) enrichSprintDashboard(result *WebSprintResult) {
	base := filepath.Join(u.root, "projects", result.Project, "sprints", result.Slug)
	requirements := readDashboardMarkdown(filepath.Join(base, "requirements.md"))
	index := readDashboardMarkdown(filepath.Join(base, "sprint-index.md"))
	result.Mission = WebSprintMission{
		Goal:               requirements.first("sprint goal", "goal"),
		Output:             requirements.first("planned output", "deliverable", "outcome"),
		Dependency:         index.first("dependencies", "dependency status"),
		NonGoals:           requirements.items("non-goals", "non goals"),
		AcceptanceCriteria: countDashboardItems(requirements, "acceptance criteria"),
		OpenQuestions:      countDashboardItems(requirements, "open questions"),
	}
	if result.Mission.Goal == "" {
		result.Mission.Goal = result.Overview
	}
	reasoning := readDashboardMarkdown(filepath.Join(base, "reasoning.md"))
	result.Decisions = reasoning.items("final decisions", "decisions", "decision summary")
	if len(result.Decisions) > 3 {
		result.Decisions = result.Decisions[:3]
	}
	result.UnresolvedRisk = reasoning.first("unresolved risks", "risks", "open questions")
	result.DeferredDecisions = countDashboardItems(reasoning, "deferred", "deferred scope")
	if result.Execute.Total > 0 {
		result.ExecutionPercent = result.Execute.Complete * 100 / result.Execute.Total
	}
	preferred := map[string]bool{"requirements": true, "reasoning": true, "plan": true, "execute": true, "review": true, "smoke": true}
	for _, artifact := range result.Artifacts {
		if preferred[artifact.Label] {
			result.Evidence = append(result.Evidence, artifact)
		}
		if len(result.Evidence) == 3 {
			break
		}
	}
}

func (u *webUseCases) enrichStudyDashboard(result *WebStudyResult) {
	for _, source := range result.Sources {
		result.SourcePreview = append(result.SourcePreview, source)
		if len(result.SourcePreview) == 4 {
			break
		}
	}
	seen := map[string]bool{}
	for _, dimension := range result.Dimensions {
		group := dashboardDimensionGroup(dimension)
		if !seen[group] {
			seen[group] = true
			result.DimensionGroups = append(result.DimensionGroups, group)
		}
		if len(result.DimensionGroups) == 4 {
			break
		}
	}
	for _, task := range result.Tasks {
		if task.Status == "waiting" || task.Status == "retrying" {
			result.Waiting++
		}
	}
	for _, source := range result.SourcePreview {
		row := WebStudyMatrixRow{Source: source}
		for _, group := range result.DimensionGroups {
			status, matched, complete, matchedCount := "pending", false, 0, 0
			for _, task := range result.Tasks {
				if task.Source != source || dashboardDimensionGroup(task.Dimension) != group {
					continue
				}
				matched = true
				matchedCount++
				switch task.Status {
				case "failed", "cancelled":
					status = "failed"
				case "running", "retrying":
					if status != "failed" {
						status = "running"
					}
				case "complete", "completed":
					complete++
				case "inapplicable", "skipped":
					if status == "pending" {
						status = "inapplicable"
					}
				}
			}
			if matched && status == "pending" && complete == matchedCount {
				status = "complete"
			}
			row.Cells = append(row.Cells, WebStudyMatrixCell{Group: group, Status: status})
		}
		result.MatrixRows = append(result.MatrixRows, row)
	}
	for i := len(result.Artifacts) - 1; i >= 0 && len(result.RecentReports) < 3; i-- {
		artifact := result.Artifacts[i]
		if strings.Contains(strings.ToLower(artifact.Label), "report") || strings.Contains(strings.ToLower(artifact.DisplayPath), "report") {
			parsed := readDashboardMarkdown(filepath.Join(u.root, filepath.FromSlash(artifact.DisplayPath)))
			result.RecentReports = append(result.RecentReports, WebReportPreview{Ref: artifact.Ref, Label: artifact.Label, DisplayPath: artifact.DisplayPath, Summary: parsed.first("summary", "synthesis", "finding")})
		}
	}
}

func dashboardDimensionGroup(value string) string {
	if cut := strings.IndexAny(value, "-_. "); cut > 0 {
		return value[:cut]
	}
	return value
}

// annotateStageModels records which model each stage will use when the
// operator leaves the model input empty, plus the model that the most recent
// completed run of each stage actually used. Both come from read-only state:
// the effective planning configuration and sprint runtime metrics.
func (u *webUseCases) annotateStageModels(result *WebSprintResult) {
	for index := range result.RunStages {
		stage := sprint.PlanningStage(result.RunStages[index].Name)
		if runtime, ok := u.dashboard.stageRuntime[stage]; ok {
			result.RunStages[index].ConfiguredModel = strings.TrimSpace(runtime.Model)
		}
	}
	metrics, err := sprint.NewService(u.root).RuntimeMetrics(result.Project, result.Slug)
	if err != nil {
		return
	}
	for _, run := range metrics.Runs {
		if strings.TrimSpace(run.Model) == "" || run.Status != "completed" {
			continue
		}
		for index := range result.RunStages {
			if sprint.PlanningStage(result.RunStages[index].Name) == run.Stage {
				result.RunStages[index].RunModel = run.Model
			}
		}
	}
}

func sprintRunStages(item SprintSummary) []StageSummary {
	stages := append([]StageSummary(nil), item.Stages...)
	executeStatus := "waiting"
	if item.Execute.Available {
		switch {
		case item.Execute.Running > 0:
			executeStatus = "running"
		case item.Execute.Failed > 0:
			executeStatus = "failed"
		case item.Execute.Total > 0 && item.Execute.Complete+item.Execute.Deferred == item.Execute.Total:
			executeStatus = "complete"
		default:
			executeStatus = "ready"
		}
	}
	stages = append(stages, StageSummary{Name: "execute", Status: executeStatus, Error: item.Execute.Message})
	reviewStatus := "waiting"
	if item.Review.Available {
		reviewStatus = item.Review.Status
		if reviewStatus == "" {
			reviewStatus = "ready"
		}
	}
	stages = append(stages, StageSummary{Name: "review", Status: reviewStatus, Error: item.Review.Error})
	smokeStatus := "waiting"
	if item.Smoke.Available {
		smokeStatus = item.Smoke.Status
		if smokeStatus == "" {
			smokeStatus = "ready"
		}
	}
	stages = append(stages, StageSummary{Name: "smoke", Status: smokeStatus, Error: item.Smoke.Error})
	mergeStatus := "waiting"
	if item.Merge.Available {
		mergeStatus = item.Merge.Status
		if mergeStatus == "" {
			mergeStatus = "ready"
		}
	}
	stages = append(stages, StageSummary{Name: "merge", Status: mergeStatus, Error: item.Merge.Error})
	for index := range stages {
		contract := sprint.InputContract(sprint.PlanningStage(stages[index].Name))
		stages[index].PromptContract = &contract
	}
	return stages
}

func (u *webUseCases) Studies(ctx context.Context) (WebStudiesResult, error) {
	items, err := u.dashboard.StudySummaries(ctx)
	if err != nil {
		return WebStudiesResult{}, err
	}
	total := len(items)
	items = bounded(items)
	out := make([]WebStudyResult, 0, len(items))
	for _, item := range items {
		out = append(out, u.webStudy(item))
	}
	return WebStudiesResult{Items: out, CollectionInfo: collectionInfo(len(out), total)}, nil
}

func (u *webUseCases) Study(ctx context.Context, name string) (WebStudyResult, error) {
	items, err := u.dashboard.StudySummaries(ctx)
	if err != nil {
		return WebStudyResult{}, err
	}
	for _, item := range items {
		if item.Name == name {
			result := u.webStudy(item)
			if listing, listErr := study.NewService(u.root).ListStudy(name); listErr == nil {
				if history, histErr := study.LoadRunLoopResourceHistory(listing.Study, 240); histErr == nil {
					throttle := study.SummarizeParallelismThrottle(history)
					result.Parallelism = &ParallelismSummary{Decreased: throttle.Decreased, Events: throttle.Events, RequestedParallelism: throttle.RequestedParallelism, EffectiveParallelism: throttle.EffectiveParallelism}
				}
			}
			u.enrichStudyDashboard(&result)
			return result, nil
		}
	}
	return WebStudyResult{}, ErrWebNotFound
}

func (u *webUseCases) Validations(ctx context.Context, scope, ref string) (WebValidationResult, error) {
	target, ok := u.resolve(ref, scope)
	if !ok {
		return WebValidationResult{}, ErrWebNotFound
	}
	var findings []DisplayFinding
	switch scope {
	case "workspace":
		if err := ctx.Err(); err != nil {
			return WebValidationResult{}, err
		}
		result := workspace.Validate(u.root)
		for _, issue := range result.Issues {
			findings = append(findings, DisplayFinding{Severity: "error", Section: "workspace", Problem: displaySafe(issue)})
		}
	case "project":
		result, err := u.Project(ctx, target.values[0])
		if err != nil {
			return WebValidationResult{}, err
		}
		findings = append(findings, result.Findings...)
	case "sprint":
		result, err := u.Sprint(ctx, target.values[0], target.values[1])
		if err != nil {
			return WebValidationResult{}, err
		}
		findings = append(findings, result.Findings...)
	case "study":
		result, err := u.Study(ctx, target.values[0])
		if err != nil {
			return WebValidationResult{}, err
		}
		findings = append(findings, result.Findings...)
	default:
		return WebValidationResult{}, ErrWebNotFound
	}
	total := len(findings)
	findings = bounded(findings)
	if findings == nil {
		findings = []DisplayFinding{}
	}
	return WebValidationResult{Scope: scope, Ref: ref, Findings: findings, CollectionInfo: collectionInfo(len(findings), total)}, nil
}

func (u *webUseCases) Artifact(ctx context.Context, ref string) (WebArtifactPreview, error) {
	target, ok := u.resolve(ref, "artifact")
	if !ok || len(target.values) != 1 {
		return WebArtifactPreview{}, ErrWebNotFound
	}
	rel := target.values[0]
	if err := ctx.Err(); err != nil {
		return WebArtifactPreview{}, err
	}
	if !supportedPreviewPath(rel) {
		return WebArtifactPreview{}, ErrWebNotFound
	}
	path, err := u.containedArtifactPath(rel)
	if err != nil {
		return WebArtifactPreview{}, ErrWebNotFound
	}
	file, err := os.Open(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return WebArtifactPreview{}, ErrWebNotFound
		}
		return WebArtifactPreview{}, fmt.Errorf("%w: artifact read", ErrWebUnavailable)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() {
		return WebArtifactPreview{}, ErrWebNotFound
	}
	data, err := io.ReadAll(io.LimitReader(file, WebPreviewByteLimit+1))
	if err != nil {
		return WebArtifactPreview{}, fmt.Errorf("%w: artifact read", ErrWebUnavailable)
	}
	truncated := len(data) > WebPreviewByteLimit
	if truncated {
		data = data[:WebPreviewByteLimit]
	}
	media := mediaTypeForPath(rel)
	return WebArtifactPreview{
		Ref:           ref,
		DisplayPath:   filepath.ToSlash(rel),
		MediaType:     media,
		Content:       string(data),
		SizeBytes:     info.Size(),
		ReturnedBytes: len(data),
		Truncated:     truncated,
		JSONValid:     media != "application/json" || json.Valid(data),
	}, nil
}

func (u *webUseCases) Health(ctx context.Context) (WebHealthResult, error) {
	if err := ctx.Err(); err != nil {
		return WebHealthResult{}, err
	}
	info, err := os.Stat(filepath.Join(u.root, workspace.MarkerFile))
	available := err == nil && !info.IsDir()
	status := "ok"
	if !available {
		status = "unavailable"
	}
	return WebHealthResult{Status: status, Server: true, Workspace: available}, nil
}

func (u *webUseCases) webProject(item ProjectSummary, sprints []WebSprintResult) WebProjectResult {
	docs := append([]string(nil), item.MarkdownDocs...)
	if docs == nil {
		docs = []string{}
	}
	findings := bounded(append([]DisplayFinding(nil), item.Findings...))
	if findings == nil {
		findings = []DisplayFinding{}
	}
	return WebProjectResult{
		Ref:              u.issue("project", item.Name),
		Name:             item.Name,
		Docs:             docs,
		Findings:         findings,
		Artifacts:        u.webArtifacts(item.Artifacts),
		Sprints:          nonNil(sprints),
		ProjectReasoning: item.ProjectReasoning,
	}
}

func (u *webUseCases) webSprint(item SprintSummary) WebSprintResult {
	stages := append([]StageSummary(nil), item.Stages...)
	if stages == nil {
		stages = []StageSummary{}
	}
	findings := bounded(append([]DisplayFinding(nil), item.Findings...))
	if findings == nil {
		findings = []DisplayFinding{}
	}
	result := WebSprintResult{
		Ref:                 u.issue("sprint", item.Project, item.Slug),
		Project:             item.Project,
		Slug:                item.Slug,
		Status:              item.Status,
		Assessment:          item.Assessment,
		NextAction:          displaySafe(item.NextAction),
		Stages:              stages,
		Execute:             item.Execute,
		Review:              item.Review,
		Smoke:               item.Smoke,
		QA:                  item.QA,
		Performance:         item.Performance,
		PerformanceEvidence: item.PerformanceEvidence,
		Findings:            findings,
		Artifacts:           u.webArtifacts(item.Artifacts),
	}
	result.ExecuteHealth = "waiting"
	switch {
	case item.Execute.Failed > 0:
		result.ExecuteHealth = "failed"
	case item.Execute.Running > 0:
		result.ExecuteHealth = "running"
	case item.Execute.Total > 0 && item.Execute.Complete+item.Execute.Deferred == item.Execute.Total:
		result.ExecuteHealth = "complete"
	}
	result.ReviewHealth = "waiting"
	switch {
	case item.Review.Stale:
		result.ReviewHealth = "stale"
	case item.Review.Failed > 0:
		result.ReviewHealth = "failed"
	case item.Review.Status == "complete" || item.Review.Status == "completed":
		result.ReviewHealth = "complete"
	case item.Review.Running > 0:
		result.ReviewHealth = "running"
	}
	result.SmokeHealth = "waiting"
	switch {
	case item.Smoke.Stale:
		result.SmokeHealth = "stale"
	case item.Smoke.Status == "failed" || item.Smoke.Verdict == "fail":
		result.SmokeHealth = "failed"
	case item.Smoke.Status == "complete" || item.Smoke.Status == "completed":
		result.SmokeHealth = "complete"
	case item.Smoke.Status == "running":
		result.SmokeHealth = "running"
	}
	return result
}

func (u *webUseCases) webStudy(item StudySummary) WebStudyResult {
	findings := bounded(append([]DisplayFinding(nil), item.Findings...))
	if findings == nil {
		findings = []DisplayFinding{}
	}
	retried := make([]WebStudyTaskRetry, 0, len(item.Tasks))
	for _, task := range item.Tasks {
		if task.Retries == 0 && task.Status != "retrying" {
			continue
		}
		retries := task.Retries
		if retries == 0 {
			retries = 1
		}
		retried = append(retried, WebStudyTaskRetry{ID: task.ID, Kind: task.Kind, Status: task.Status, Retries: retries, SessionReuse: task.SessionReuse})
	}
	if retried == nil {
		retried = []WebStudyTaskRetry{}
	}
	return WebStudyResult{
		Ref:          u.issue("study", item.Name),
		Name:         item.Name,
		Sources:      nonNil(append([]string(nil), item.Sources...)),
		Dimensions:   nonNil(append([]string(nil), item.Dimensions...)),
		Status:       item.Status,
		RunID:        displaySafe(item.RunID),
		Total:        item.Total,
		Completed:    item.Completed,
		Failed:       item.Failed,
		RunActive:    item.RunActive,
		ActiveTasks:  item.ActiveTasks,
		Pending:      item.Pending,
		Cancelled:    item.Cancelled,
		Retries:      item.Retries,
		RetriedTasks: retried,
		Tasks:        append([]RunTaskSummary(nil), item.Tasks...),
		Findings:     findings,
		Artifacts:    u.webArtifacts(item.Artifacts),
	}
}

func (u *webUseCases) webArtifacts(items []DisplayArtifact) []WebArtifactLink {
	out := make([]WebArtifactLink, 0, len(items))
	for _, item := range items {
		rel := filepath.ToSlash(filepath.Clean(filepath.FromSlash(item.Path)))
		if filepath.IsAbs(rel) || !supportedPreviewPath(rel) {
			continue
		}
		out = append(out, WebArtifactLink{
			Ref:         u.issue("artifact", rel),
			Label:       item.Label,
			DisplayPath: rel,
			MediaType:   mediaTypeForPath(rel),
		})
		if len(out) == WebCollectionLimit {
			break
		}
	}
	if out == nil {
		return []WebArtifactLink{}
	}
	return out
}

func (u *webUseCases) issue(kind string, values ...string) string {
	mac := hmac.New(sha256.New, u.secret[:])
	_, _ = mac.Write([]byte(kind))
	for _, value := range values {
		_, _ = mac.Write([]byte{0})
		_, _ = mac.Write([]byte(value))
	}
	ref := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
	target := webRefTarget{kind: kind, values: append([]string(nil), values...)}
	u.mu.Lock()
	u.refs[ref] = target
	u.mu.Unlock()
	return ref
}

func (u *webUseCases) resolve(ref, kind string) (webRefTarget, bool) {
	u.mu.RLock()
	target, ok := u.refs[ref]
	u.mu.RUnlock()
	return target, ok && target.kind == kind
}

func (u *webUseCases) containedArtifactPath(rel string) (string, error) {
	path, err := workspace.ResolveInside(u.root, rel)
	if err != nil {
		return "", err
	}
	root, err := filepath.EvalSymlinks(u.root)
	if err != nil {
		return "", err
	}
	path, err = filepath.EvalSymlinks(path)
	if err != nil {
		return "", err
	}
	inside, err := filepath.Rel(root, path)
	if err != nil || inside == ".." || strings.HasPrefix(inside, ".."+string(filepath.Separator)) {
		return "", errors.New("artifact escapes workspace")
	}
	return path, nil
}

func mediaTypeForPath(path string) string {
	if strings.EqualFold(filepath.Ext(path), ".json") {
		return "application/json"
	}
	return "text/markdown"
}

func bounded[T any](items []T) []T {
	if len(items) > WebCollectionLimit {
		items = items[:WebCollectionLimit]
	}
	return items
}

func nonNil[T any](items []T) []T {
	if items == nil {
		return []T{}
	}
	return items
}

func collectionInfo(returned, total int) CollectionInfo {
	return CollectionInfo{ReturnedCount: returned, TotalCount: total, Truncated: returned < total}
}

package sprint

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"time"
)

const performanceHardStateBytes = 128 << 20
const performanceEvidenceScanLimit = 4096

var performanceAttemptID = regexp.MustCompile(`^performance-v1-attempt-[a-f0-9]{24}$`)

type PerformanceStore struct {
	root   string
	sprint Sprint
	fence  func(VerificationWriterToken) error
	hooks  QAStateHooks
}

func (store PerformanceStore) ReadJSON(ref PerformanceArtifactRef, value any) error {
	data, err := store.ReadBytes(ref)
	if err != nil {
		return err
	}
	return jsonNewStrictDecoder(data)(value)
}

func (store PerformanceStore) ReadBytes(ref PerformanceArtifactRef) ([]byte, error) {
	path, err := store.resolve(ref.Path)
	if err != nil {
		return nil, err
	}
	if err := performanceNoFollow(path, store.sprint.Path); err != nil {
		return nil, err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	if len(data) == 0 || len(data) > performanceHardStateBytes || hashBytes(data) != ref.Digest {
		return nil, fmt.Errorf("performance artifact digest mismatch")
	}
	return data, nil
}

type PerformanceEvidenceRecord struct {
	AttemptID string `json:"attempt_id"`
	Name      string `json:"name"`
	Path      string `json:"path"`
	Digest    string `json:"digest"`
	Size      int64  `json:"size_bytes"`
}

type PerformanceEvidencePage struct {
	Records    []PerformanceEvidenceRecord `json:"records"`
	NextCursor string                      `json:"next_cursor,omitempty"`
}

// EvidencePage performs a bounded, attempt-scoped metadata query. It never
// returns artifact contents or reconstructs state by walking old attempts.
func (store PerformanceStore) EvidencePage(attemptID, cursor, filter string, limit int) (PerformanceEvidencePage, error) {
	if !performanceAttemptID.MatchString(attemptID) {
		return PerformanceEvidencePage{}, fmt.Errorf("invalid performance attempt ID")
	}
	if limit <= 0 || limit > MaxPerformanceLimits().EvidencePageSize {
		return PerformanceEvidencePage{}, fmt.Errorf("invalid performance evidence page size")
	}
	baseRel, _ := PerformanceAttemptRelPath(store.sprint, attemptID, "placeholder")
	base, err := store.resolve(filepath.Dir(baseRel))
	if err != nil {
		return PerformanceEvidencePage{}, err
	}
	capacity := limit * 2
	if capacity > performanceEvidenceScanLimit {
		capacity = performanceEvidenceScanLimit
	}
	names := make([]string, 0, capacity)
	scanned := 0
	err = filepath.WalkDir(base, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if path == base {
			return nil
		}
		scanned++
		if scanned > performanceEvidenceScanLimit {
			return fmt.Errorf("performance evidence scan exceeds %d entries", performanceEvidenceScanLimit)
		}
		if entry.Type()&os.ModeSymlink != 0 {
			return fmt.Errorf("performance evidence contains a symbolic link")
		}
		if entry.IsDir() {
			return nil
		}
		if !entry.Type().IsRegular() {
			return fmt.Errorf("performance evidence contains a non-regular record")
		}
		rel, relErr := filepath.Rel(base, path)
		if relErr != nil {
			return relErr
		}
		name := filepath.ToSlash(rel)
		if strings.Contains(name, filter) {
			names = append(names, name)
		}
		return nil
	})
	if err != nil {
		return PerformanceEvidencePage{}, err
	}
	sort.Strings(names)
	page := PerformanceEvidencePage{}
	for _, name := range names {
		if cursor != "" && name <= cursor {
			continue
		}
		if len(page.Records) == limit {
			page.NextCursor = page.Records[len(page.Records)-1].Name
			break
		}
		path := filepath.Join(base, filepath.FromSlash(name))
		info, statErr := os.Lstat(path)
		if statErr != nil || !info.Mode().IsRegular() || info.Mode()&os.ModeSymlink != 0 {
			return PerformanceEvidencePage{}, fmt.Errorf("unsafe performance evidence record %q", name)
		}
		if info.Size() <= 0 || info.Size() > performanceHardStateBytes {
			return PerformanceEvidencePage{}, fmt.Errorf("performance evidence record %q exceeds the query bound", name)
		}
		data, readErr := os.ReadFile(path)
		if readErr != nil {
			return PerformanceEvidencePage{}, readErr
		}
		rel := filepath.ToSlash(filepath.Join(filepath.Dir(baseRel), name))
		page.Records = append(page.Records, PerformanceEvidenceRecord{AttemptID: attemptID, Name: name, Path: rel, Digest: hashBytes(data), Size: info.Size()})
	}
	return page, nil
}

// PruneTerminalAttempts retains the newest bounded terminal attempts and never
// removes the current attempt. Nonterminal or malformed directories are left
// untouched for explicit recovery.
func (store PerformanceStore) PruneTerminalAttempts(current string, retain int) error {
	if retain <= 0 || retain > MaxPerformanceLimits().RetainedAttempts || !performanceAttemptID.MatchString(current) {
		return fmt.Errorf("invalid performance retention request")
	}
	baseRel := filepath.ToSlash(filepath.Join("projects", store.sprint.Project, "sprints", store.sprint.Slug, "verification", "performance", "attempts"))
	base, err := store.resolve(baseRel)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	entries, err := os.ReadDir(base)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	type candidate struct {
		name string
		mod  time.Time
	}
	var values []candidate
	for _, entry := range entries {
		if !entry.IsDir() || !performanceAttemptID.MatchString(entry.Name()) {
			continue
		}
		resultRel, _ := PerformanceAttemptRelPath(store.sprint, entry.Name(), "result.json")
		resultPath, resolveErr := store.resolve(resultRel)
		if resolveErr != nil {
			continue
		}
		info, statErr := os.Lstat(resultPath)
		if statErr != nil || !info.Mode().IsRegular() {
			continue
		}
		values = append(values, candidate{name: entry.Name(), mod: info.ModTime()})
	}
	sort.Slice(values, func(i, j int) bool {
		if values[i].mod.Equal(values[j].mod) {
			return values[i].name > values[j].name
		}
		return values[i].mod.After(values[j].mod)
	})
	kept := map[string]bool{current: true}
	for _, value := range values {
		if len(kept) >= retain {
			break
		}
		kept[value.name] = true
	}
	for _, value := range values {
		if kept[value.name] {
			continue
		}
		path, resolveErr := store.resolve(filepath.ToSlash(filepath.Join(baseRel, value.name)))
		if resolveErr != nil {
			return resolveErr
		}
		if err := os.RemoveAll(path); err != nil {
			return err
		}
	}
	return nil
}

func NewPerformanceStore(root string, sprint Sprint) PerformanceStore {
	return PerformanceStore{root: root, sprint: sprint}
}

func (store PerformanceStore) WithWriterFence(fence func(VerificationWriterToken) error) PerformanceStore {
	store.fence = fence
	return store
}

func (store PerformanceStore) WithHooks(hooks QAStateHooks) PerformanceStore {
	store.hooks = hooks
	return store
}

func PerformanceStateRelPath(s Sprint) string {
	return filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug, "verification", "performance-state.json"))
}

func PerformanceReportRelPath(s Sprint) string {
	return filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug, "performance.md"))
}

func PerformanceAttemptRelPath(s Sprint, attemptID, name string) (string, error) {
	if !performanceAttemptID.MatchString(attemptID) {
		return "", fmt.Errorf("invalid performance attempt ID")
	}
	if name == "" || filepath.Base(name) != name || strings.ContainsAny(name, "\x00/\\") {
		return "", fmt.Errorf("invalid performance record name")
	}
	return filepath.ToSlash(filepath.Join("projects", s.Project, "sprints", s.Slug, "verification", "performance", "attempts", attemptID, name)), nil
}

func PerformanceCycleRelPath(s Sprint, attemptID string, cycle int, name string) (string, error) {
	if cycle <= 0 {
		return "", fmt.Errorf("invalid performance cycle")
	}
	base, err := PerformanceAttemptRelPath(s, attemptID, "placeholder")
	if err != nil {
		return "", err
	}
	base = filepath.Dir(base)
	if name == "" || filepath.Base(name) != name || strings.ContainsAny(name, "\x00/\\") {
		return "", fmt.Errorf("invalid performance record name")
	}
	return filepath.ToSlash(filepath.Join(base, "cycles", fmt.Sprintf("%06d", cycle), name)), nil
}

func (store PerformanceStore) PublishJSON(rel, kind string, value any, immutable bool, token VerificationWriterToken) (PerformanceArtifactRef, error) {
	if err := store.checkWriter(token); err != nil {
		return PerformanceArtifactRef{}, err
	}
	data, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return PerformanceArtifactRef{}, fmt.Errorf("encode performance %s: %w", kind, err)
	}
	data = append(data, '\n')
	return store.publishBytes(rel, kind, data, immutable, token)
}

func (store PerformanceStore) PublishBytes(rel, kind string, data []byte, immutable bool, token VerificationWriterToken) (PerformanceArtifactRef, error) {
	if err := store.checkWriter(token); err != nil {
		return PerformanceArtifactRef{}, err
	}
	return store.publishBytes(rel, kind, data, immutable, token)
}

func (store PerformanceStore) publishBytes(rel, kind string, data []byte, immutable bool, token VerificationWriterToken) (PerformanceArtifactRef, error) {
	if len(data) == 0 || len(data) > performanceHardStateBytes {
		return PerformanceArtifactRef{}, fmt.Errorf("performance %s exceeds the retained record limit", kind)
	}
	path, err := store.resolve(rel)
	if err != nil {
		return PerformanceArtifactRef{}, err
	}
	if err := performanceNoFollow(path, store.sprint.Path); err != nil {
		return PerformanceArtifactRef{}, err
	}
	if immutable {
		current, readErr := os.ReadFile(path)
		if readErr == nil {
			if bytes.Equal(current, data) {
				return PerformanceArtifactRef{Path: rel, Digest: hashBytes(data)}, nil
			}
			return PerformanceArtifactRef{}, fmt.Errorf("immutable performance %s already exists with different bytes", kind)
		}
		if !errors.Is(readErr, fs.ErrNotExist) {
			return PerformanceArtifactRef{}, fmt.Errorf("inspect performance %s: %w", kind, readErr)
		}
	}
	hooks := store.hooks
	beforeRename := hooks.BeforeRename
	hooks.BeforeRename = func(hookKind, hookPath string) error {
		if err := store.checkWriter(token); err != nil {
			return err
		}
		if beforeRename != nil {
			return beforeRename(hookKind, hookPath)
		}
		return nil
	}
	if hooks.BeforeStep != nil {
		if err := hooks.BeforeStep(kind, path); err != nil {
			return PerformanceArtifactRef{}, err
		}
	}
	var writeErr error
	if immutable {
		writeErr = privateImmutableWrite(path, data, "performance-"+kind, hooks)
	} else {
		writeErr = privateAtomicWrite(path, data, "performance-"+kind, hooks)
	}
	if errors.Is(writeErr, errImmutableRecordConflict) {
		return PerformanceArtifactRef{}, fmt.Errorf("immutable performance %s already exists with different bytes", kind)
	}
	if writeErr != nil {
		return PerformanceArtifactRef{}, fmt.Errorf("publish performance %s: %w", kind, writeErr)
	}
	return PerformanceArtifactRef{Path: rel, Digest: hashBytes(data)}, nil
}

func (store PerformanceStore) PublishState(state PerformanceState, token VerificationWriterToken) (PerformanceArtifactRef, error) {
	if err := validatePerformanceState(state, store.sprint); err != nil {
		return PerformanceArtifactRef{}, err
	}
	return store.PublishJSON(PerformanceStateRelPath(store.sprint), "state", state, false, token)
}

func LoadPerformanceState(root string, sprint Sprint) (PerformanceState, error) {
	path, err := resolveSprintContained(root, sprint, PerformanceStateRelPath(sprint))
	if err != nil {
		return PerformanceState{}, err
	}
	if err := performanceNoFollow(path, sprint.Path); err != nil {
		return PerformanceState{}, err
	}
	file, err := os.Open(path)
	if err != nil {
		return PerformanceState{}, err
	}
	defer file.Close()
	decoder := json.NewDecoder(io.LimitReader(file, performanceHardStateBytes+1))
	decoder.DisallowUnknownFields()
	var state PerformanceState
	if err := decoder.Decode(&state); err != nil {
		return PerformanceState{}, fmt.Errorf("decode performance state: %w", err)
	}
	if err := decoder.Decode(&struct{}{}); err != io.EOF {
		return PerformanceState{}, fmt.Errorf("decode performance state: trailing data")
	}
	if err := validatePerformanceState(state, sprint); err != nil {
		return PerformanceState{}, err
	}
	return state, nil
}

func validatePerformanceState(state PerformanceState, sprint Sprint) error {
	if state.SchemaVersion != PerformanceSchemaVersion || state.Project != sprint.Project || state.Sprint != sprint.Slug || !performanceAttemptID.MatchString(state.AttemptID) {
		return fmt.Errorf("invalid performance state identity")
	}
	if err := state.Correlation.Validate(); err != nil {
		return err
	}
	if state.Deadline.IsZero() || state.UpdatedAt.IsZero() || strings.TrimSpace(state.NextAction) == "" || state.Packet.Path == "" || !validFingerprint(state.Packet.Digest) || !validFingerprint(state.TargetPacketDigest) {
		return fmt.Errorf("incomplete performance state")
	}
	if err := ValidatePerformanceLimits(state.Limits); err != nil {
		return err
	}
	if err := validatePerformanceCounters(state.Counters, state.Limits); err != nil {
		return err
	}
	if err := validatePerformanceStateRef(state, state.Packet, "target-packet.json", true); err != nil {
		return err
	}
	for _, ref := range []struct {
		value    *PerformanceArtifactRef
		name     string
		required bool
	}{{state.Manifest, "benchmark-manifest.json", state.Phase != PerformancePhasePreparing}, {state.Environment, "environment.json", state.Phase != PerformancePhasePreparing}, {state.Baseline, "baseline.json", state.Phase == PerformancePhaseOptimizing || state.Phase == PerformancePhaseFinalizing}, {state.Final, "final.json", false}, {state.Result, "result.json", state.Phase == PerformancePhaseTerminal}} {
		if ref.value == nil {
			if ref.required {
				return fmt.Errorf("performance state is missing %s", ref.name)
			}
			continue
		}
		if err := validatePerformanceStateRef(state, *ref.value, ref.name, true); err != nil {
			return err
		}
	}
	if state.ApplyJournal != nil {
		if state.Counters.OptimizationCycles <= 0 {
			return fmt.Errorf("performance state has an apply journal without a cycle")
		}
		want, pathErr := PerformanceCycleRelPath(sprint, state.AttemptID, state.Counters.OptimizationCycles, "apply-journal.json")
		if pathErr != nil || state.ApplyJournal.Path != want || !validFingerprint(state.ApplyJournal.Digest) {
			return fmt.Errorf("performance state has an invalid apply-journal reference")
		}
	}
	if state.AcceptedMutations < 0 || state.AcceptedMutations > state.Limits.OptimizationCycles {
		return fmt.Errorf("performance state has an invalid accepted-mutation count")
	}
	if state.CurrentImplementation != "" && !validFingerprint(state.CurrentImplementation) {
		return fmt.Errorf("performance state has an invalid current implementation")
	}
	for name, digest := range map[string]string{
		"requirements": state.Freshness.RequirementsDigest, "policy": state.Freshness.PolicyDigest,
		"execute": state.Freshness.ExecuteDigest, "packet": state.Freshness.PacketDigest,
		"manifest": state.Freshness.ManifestDigest, "correctness": state.Freshness.CorrectnessDigest,
		"process_policy": state.Freshness.ProcessPolicyDigest, "environment": state.Freshness.EnvironmentIdentity,
		"workflow": state.Freshness.WorkflowDigest, "initial_implementation": state.Freshness.InitialImplementation,
		"final_implementation": state.Freshness.FinalImplementation, "result": state.Freshness.ResultDigest,
	} {
		if digest != "" && !validFingerprint(digest) {
			return fmt.Errorf("performance state has an invalid %s freshness digest", name)
		}
	}
	switch state.Phase {
	case PerformancePhaseReady, PerformancePhasePreparing, PerformancePhaseBaseline, PerformancePhaseOptimizing, PerformancePhaseFinalizing, PerformancePhaseTerminal, PerformancePhaseStale:
	default:
		return fmt.Errorf("invalid performance state phase")
	}
	if state.Phase == PerformancePhaseTerminal && !validPerformanceRunOutcome(state.Outcome) {
		return fmt.Errorf("terminal performance state has an invalid outcome")
	}
	if len(state.FreshnessReasons) > 32 || len(state.Blocker) > 512 || len(state.NextAction) > 1024 {
		return fmt.Errorf("performance state text exceeds its bound")
	}
	return nil
}

func validatePerformanceCounters(counters PerformanceCounters, limits PerformanceLimits) error {
	if counters.Commands < 0 || counters.Commands > limits.Commands || counters.Warmups < 0 || counters.Warmups > counters.Commands || counters.Samples < 0 || counters.Samples > counters.Commands || counters.OptimizationCycles < 0 || counters.OptimizationCycles > limits.OptimizationCycles || counters.RuntimeAttempts < 0 {
		return fmt.Errorf("performance counters exceed the persisted attempt limits")
	}
	maxRuntimeAttempts := limits.AuthoringAttempts + limits.OptimizationCycles*limits.OptimizationAttempts
	if counters.RuntimeAttempts > maxRuntimeAttempts {
		return fmt.Errorf("performance runtime attempts exceed the persisted attempt limits")
	}
	return nil
}

func validatePerformanceStateRef(state PerformanceState, ref PerformanceArtifactRef, name string, required bool) error {
	if !required && ref.Path == "" && ref.Digest == "" {
		return nil
	}
	want, err := PerformanceAttemptRelPath(Sprint{Project: state.Project, Slug: state.Sprint}, state.AttemptID, name)
	if err != nil || ref.Path != want || !validFingerprint(ref.Digest) {
		return fmt.Errorf("performance state has an invalid %s reference", name)
	}
	return nil
}

func validPerformanceRunOutcome(outcome PerformanceRunOutcome) bool {
	switch outcome {
	case PerformancePassed, PerformancePassedWithReports, PerformanceTargetMiss, PerformanceBlocked, PerformanceStalled, PerformanceCancelled, PerformanceCleanupUncertain:
		return true
	default:
		return false
	}
}

func (store PerformanceStore) checkWriter(token VerificationWriterToken) error {
	if err := token.Validate(); err != nil {
		return fmt.Errorf("invalid performance writer: %w", err)
	}
	if store.fence == nil {
		return fmt.Errorf("no verification writer fence is configured")
	}
	if err := store.fence(token); err != nil {
		return fmt.Errorf("performance writer is stale: %w", err)
	}
	return nil
}

func (store PerformanceStore) resolve(rel string) (string, error) {
	return resolveSprintContained(store.root, store.sprint, rel)
}

func performanceNoFollow(path, sprintRoot string) error {
	cleanPath, cleanRoot := filepath.Clean(path), filepath.Clean(sprintRoot)
	if cleanPath != cleanRoot && !strings.HasPrefix(cleanPath, cleanRoot+string(filepath.Separator)) {
		return fmt.Errorf("performance path escapes sprint root")
	}
	for current := cleanPath; current != cleanRoot; current = filepath.Dir(current) {
		info, err := os.Lstat(current)
		if errors.Is(err, fs.ErrNotExist) {
			continue
		}
		if err != nil {
			return err
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("performance path contains a symbolic link")
		}
	}
	return nil
}

package tui

import (
	"context"
	"fmt"
	"path/filepath"
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

type Tab string

const (
	TabProjects Tab = "projects"
	TabStudies  Tab = "studies"
	TabRuns     Tab = "runs"
)

type FocusArea string

const (
	FocusTabs    FocusArea = "tabs"
	FocusContent FocusArea = "content"
)

type RouteKind string

const (
	RouteProjects       RouteKind = "projects"
	RouteProject        RouteKind = "project"
	RouteProjectSprints RouteKind = "project-sprints"
	RouteProjectDocs    RouteKind = "project-docs"
	RouteSprint         RouteKind = "sprint"
	RouteSprintQA       RouteKind = "sprint-qa"
	RouteSprintQAShard  RouteKind = "sprint-qa-shard"
	RouteSprintQATheory RouteKind = "sprint-qa-theory"
	RouteSprintRepair   RouteKind = "sprint-repair"
	RouteStudies        RouteKind = "studies"
	RouteStudy          RouteKind = "study"
	RouteStudyDims      RouteKind = "study-dimensions"
	RouteStudySources   RouteKind = "study-sources"
	RouteRuns           RouteKind = "runs"
	RouteRun            RouteKind = "run"
)

type Route struct {
	Kind    RouteKind
	Project string
	Sprint  string
	Study   string
	RunID   string
	Shard   string
	Theory  string
}

type Model struct {
	UseCases              app.OperationalUseCases
	Data                  app.DashboardResult
	ActiveTab             Tab
	Focus                 FocusArea
	Routes                []Route
	Selected              int
	Preview               *app.ArtifactPreviewResult
	PreviewTitle          string
	Error                 string
	Loading               bool
	Quit                  bool
	PreviewOffset         int
	Validation            *app.ValidationOperationResult
	Confirmation          *app.Confirmation
	Operation             *app.OperationResult
	Events                []app.OperationEvent
	Running               bool
	RunViewStudy          string
	RunViewShowPrevious   bool
	ActiveOperation       app.OperationRequest
	OperationShowPrevious bool
	OperationHidden       bool
	ParallelForm          *app.OperationRequest
	ParallelValue         string
	ParallelError         string
	ActiveRunID           string
	Runs                  []app.RunSnapshot
	DurableEvents         []app.RunEvent
}

type Message interface{}

type LoadMsg struct {
	Result app.DashboardResult
	Runs   []app.RunSnapshot
	Events []app.RunEvent
	Err    error
}
type RefreshMsg struct {
	Result app.DashboardResult
	Runs   []app.RunSnapshot
	Events []app.RunEvent
	Err    error
}
type PreviewMsg struct {
	Result app.ArtifactPreviewResult
	Err    error
	Route  Route
	Title  string
}
type KeyMsg string
type ValidationMsg struct {
	Result app.ValidationOperationResult
	Err    error
	Route  Route
}
type ConfirmationMsg struct {
	Result app.Confirmation
	Err    error
	Route  Route
}
type OperationMsg struct {
	Result app.OperationResult
	Err    error
	Route  Route
	Events []app.OperationEvent
}
type OperationEventMsg struct{ Event app.OperationEvent }

type navItem struct {
	Label      string
	Route      *Route
	Path       string
	Validation *app.ValidationRequest
	Operation  *app.OperationRequest
	ViewRun    string
}

func NewModel(useCases app.OperationalUseCases) Model {
	return Model{
		UseCases:  useCases,
		ActiveTab: TabProjects,
		Focus:     FocusContent,
		Routes:    []Route{{Kind: RouteProjects}},
		Loading:   true,
	}
}

func (m Model) Load(ctx context.Context) (Model, error) {
	result, err := m.UseCases.Dashboard(ctx)
	return m.Update(LoadMsg{Result: result, Err: err}), err
}

func (m Model) Refresh(ctx context.Context) (Model, error) {
	result, err := m.UseCases.Dashboard(ctx)
	return m.Update(RefreshMsg{Result: result, Err: err}), err
}

func (m Model) PreviewSelected(ctx context.Context) (Model, error) {
	item, ok := m.selectedItem()
	if !ok || item.Path == "" {
		return m.Update(PreviewMsg{Result: app.ArtifactPreviewResult{Error: "no previewable artifact selected"}, Route: m.currentRoute(), Title: "Preview"}), nil
	}
	result, err := m.UseCases.PreviewArtifact(ctx, item.Path)
	return m.Update(PreviewMsg{Result: result, Err: err, Route: m.currentRoute(), Title: item.Label}), err
}

func (m Model) Update(msg Message) Model {
	switch v := msg.(type) {
	case LoadMsg:
		m.Loading = false
		if v.Err != nil {
			m.Error = v.Err.Error()
			return m
		}
		m.Data = v.Result
		m.Runs = v.Runs
		m.DurableEvents = dedupeDurableEvents(v.Events)
		m.Error = ""
		m.clampSelection()
	case RefreshMsg:
		m.Loading = false
		m.Preview = nil
		m.PreviewOffset = 0
		if v.Err != nil {
			m.Error = v.Err.Error()
			return m
		}
		m.Data = v.Result
		m.Runs = v.Runs
		m.DurableEvents = dedupeDurableEvents(v.Events)
		m.Error = ""
		m.clampSelection()
	case PreviewMsg:
		if v.Route != (Route{}) && v.Route != m.currentRoute() {
			return m
		}
		if v.Err != nil {
			m.Error = v.Err.Error()
			return m
		}
		m.Preview = &v.Result
		m.PreviewTitle = v.Title
		m.Error = ""
		m.PreviewOffset = 0
	case ValidationMsg:
		m.Loading = false
		if v.Route != m.currentRoute() {
			return m
		}
		if v.Err != nil {
			m.Error = v.Err.Error()
			return m
		}
		m.Validation = &v.Result
		m.Error = ""
	case ConfirmationMsg:
		m.Loading = false
		if v.Route != m.currentRoute() {
			return m
		}
		if v.Err != nil {
			m.Error = v.Err.Error()
			return m
		}
		m.Confirmation = &v.Result
	case OperationEventMsg:
		if !m.Running {
			return m
		}
		m.Events = append(m.Events, v.Event)
		if len(m.Events) > 100 {
			m.Events = m.Events[len(m.Events)-100:]
		}
	case OperationMsg:
		m.Running = false
		m.Loading = false
		m.Confirmation = nil
		m.Operation = &v.Result
		m.Events = append(m.Events, v.Events...)
		if len(m.Events) > 100 {
			m.Events = m.Events[len(m.Events)-100:]
		}
		if v.Err != nil {
			m.Error = v.Err.Error()
		}
	case KeyMsg:
		switch KeyToAction(string(v)) {
		case ActionQuit:
			m.Quit = true
		case ActionFocusNext:
			if m.ActiveTab == TabProjects {
				m.setTab(TabStudies)
			} else {
				m.setTab(TabProjects)
			}
		case ActionBack:
			if m.Running && !m.OperationHidden {
				return m
			} else if m.ParallelForm != nil {
				m.ParallelForm = nil
				m.ParallelValue = ""
				m.ParallelError = ""
			} else if m.RunViewStudy != "" {
				m.RunViewStudy = ""
				m.RunViewShowPrevious = false
				m.Operation = nil
				m.Events = nil
			} else if m.Confirmation != nil {
				m.Confirmation = nil
			} else if m.Operation != nil && !m.OperationHidden {
				m.Operation = nil
				m.Events = nil
				m.ActiveOperation = app.OperationRequest{}
				m.OperationShowPrevious = false
			} else if m.Validation != nil {
				m.Validation = nil
			} else if m.Preview != nil {
				m.Preview = nil
				m.PreviewOffset = 0
			} else if m.Focus == FocusContent && len(m.Routes) > 1 {
				m.Routes = m.Routes[:len(m.Routes)-1]
				m.Selected = 0
			}
		case ActionUp:
			if m.Preview != nil {
				m.PreviewOffset--
				if m.PreviewOffset < 0 {
					m.PreviewOffset = 0
				}
			} else if m.Focus == FocusContent && m.Selected > 0 {
				m.Selected--
			} else if m.Focus == FocusContent && m.Selected == 0 {
				m.Focus = FocusTabs
			}
		case ActionDown:
			if m.Preview != nil {
				m.PreviewOffset++
			} else if m.Focus == FocusTabs {
				m.Focus = FocusContent
			} else if m.Focus == FocusContent {
				m.Selected++
				m.clampSelection()
			}
		case ActionLeft:
			if m.Focus == FocusTabs {
				if m.ActiveTab == TabRuns {
					m.setTab(TabStudies)
				} else {
					m.setTab(TabProjects)
				}
				m.Focus = FocusTabs
			}
		case ActionRight:
			if m.Focus == FocusTabs {
				if m.ActiveTab == TabProjects {
					m.setTab(TabStudies)
					m.Focus = FocusTabs
				} else {
					m.Focus = FocusContent
				}
			}
		case ActionProjects:
			m.setTab(TabProjects)
		case ActionStudies:
			m.setTab(TabStudies)
		case ActionRuns:
			m.setTab(TabRuns)
		case ActionOpen:
			if m.Preview != nil {
				return m
			}
			if m.Focus == FocusTabs {
				m.Focus = FocusContent
				return m
			}
			if item, ok := m.selectedItem(); ok && item.Route != nil {
				m.Routes = append(m.Routes, *item.Route)
				m.Selected = 0
			}
		}
	}
	return m
}

func dedupeDurableEvents(events []app.RunEvent) []app.RunEvent {
	seen := make(map[string]bool, len(events))
	result := make([]app.RunEvent, 0, min(len(events), 200))
	for _, event := range events {
		key := string(event.RunID) + ":" + fmt.Sprint(event.Sequence)
		if seen[key] {
			continue
		}
		seen[key] = true
		result = append(result, event)
	}
	if len(result) > 200 {
		result = result[len(result)-200:]
	}
	return result
}

func (m *Model) setTab(tab Tab) {
	m.ActiveTab = tab
	m.Focus = FocusContent
	m.Selected = 0
	m.Preview = nil
	m.PreviewOffset = 0
	if tab == TabStudies {
		m.Routes = []Route{{Kind: RouteStudies}}
		return
	}
	if tab == TabRuns {
		m.Routes = []Route{{Kind: RouteRuns}}
		return
	}
	m.Routes = []Route{{Kind: RouteProjects}}
}

func (m *Model) clampSelection() {
	max := len(m.navItems()) - 1
	if max < 0 {
		m.Selected = 0
		return
	}
	if m.Selected > max {
		m.Selected = max
	}
}

func (m Model) currentRoute() Route {
	if len(m.Routes) == 0 {
		if m.ActiveTab == TabStudies {
			return Route{Kind: RouteStudies}
		}
		if m.ActiveTab == TabRuns {
			return Route{Kind: RouteRuns}
		}
		return Route{Kind: RouteProjects}
	}
	return m.Routes[len(m.Routes)-1]
}

func (m Model) selectedItem() (navItem, bool) {
	items := m.navItems()
	if m.Selected < 0 || m.Selected >= len(items) {
		return navItem{}, false
	}
	return items[m.Selected], true
}

func (m Model) navItems() []navItem {
	route := m.currentRoute()
	switch route.Kind {
	case RouteProjects:
		items := make([]navItem, 0, len(m.Data.Projects))
		for _, p := range m.Data.Projects {
